    name: "\u0627\u0644\u062f\u0642\u0629 \u0648\u0627\u0644\u0623\u062e\u0644\u0627\u0642\u064a\u0627\u062a \u0648\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u062e\u0627\u0637\u0631 (Detail, Ethics & Risk Orientation)",
    description: "\u0627\u0644\u062d\u0631\u0635 \u0639\u0644\u0649 \u0627\u0644\u0627\u0645\u062a\u062b\u0627\u0644\u060c \u0648\u0627\u0644\u0633\u0644\u0648\u0643 \u0627\u0644\u0623\u062e\u0644\u0627\u0642\u064a\u060c \u0648\u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0623\u062e\u0637\u0627\u0621\u060c \u0648\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u062e\u0627\u0637\u0631."
