    optionText: "\u0627\u0644\u0631\u0626\u064a\u0633 \u0627\u0644\u062a\u0646\u0641\u064a\u0630\u064a (CEO) \u0623\u0648 \u0631\u0627\u0626\u062f \u0623\u0639\u0645\u0627\u0644 \u0648\u0645\u0624\u0633\u0633 \u0634\u0631\u0643\u0627\u062a \u0623\u0648 \u0645\u0633\u062a\u0634\u0627\u0631 \u0625\u062f\u0627\u0631\u064a \u062f\u0648\u0644\u064a"
