    optionText: "\u0d12\u0d30\u0d41 \u0d1a\u0d40\u0d2b\u0d4d \u0d05\u0d28\u0d32\u0d3f\u0d31\u0d4d\u0d31\u0d3f\u0d15\u0d4d\u0d38\u0d4d \u0d13\u0d2b\u0d40\u0d38\u0d7c, \u0d2b\u0d3f\u0d7b\u0d1f\u0d46\u0d15\u0d4d \u0d38\u0d4d\u0d1f\u0d4d\u0d30\u0d3e\u0d31\u0d4d\u0d31\u0d1c\u0d3f\u0d38\u0d4d\u0d31\u0d4d\u0d31\u0d4d \u0d05\u0d32\u0d4d\u0d32\u0d46\u0d19\u0d4d\u0d15\u0d3f\u0d7d \u0d2a\u0d4d\u0d30\u0d2e\u0d41\u0d16 \u0d38\u0d3e\u0d2e\u0d4d\u0d2a\u0d24\u0d4d\u0d24\u0d3f\u0d15 \u0d36\u0d3e\u0d38\u0d4d\u0d24\u0d4d\u0d30\u0d1c\u0d4d\u0d1e\u0d7b"
